","const PASSPORT_API = '/api/x_1947064_autoca_0/vehicle_passport';

function headers(): Record<string, string> {
 return {
 Accept: 'application/json',
 'Content-Type': 'application/json',
 'X-UserToken': (window as any).g_ck,
 };
}

export async function fetchPassportSummary(vehicleId: string): Promise<any> {
 const res = await fetch(
 `${PASSPORT_API}/summary/${vehicleId}`,
 { headers: headers() }
 );
 if (!res.ok) throw new Error('Failed to fetch passport summary');
 const data = await res.json();
 return data.result;
}
","import React, { useEffect, useState } from 'react';
import { Card } from '@servicenow/react-components/Card';
import { fetchPassportSummary } from '../services/passportService';

interface Props {
 vehicleId: string;
}

export default function PassportSummary({ vehicleId }: Props) {
 const [data, setData] = useState<any>(null);
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 setLoading(true);
 fetchPassportSummary(vehicleId)
 .then(setData)
 .catch(() => setData(null))
 .finally(() => setLoading(false));
 }, [vehicleId]);

 if (loading) return <div className="vhp-loading">Loading summary...</div>;
 if (!data) return <div className="vhp-error">Unable to load summary</div>;

 const v = data.vehicle || {};
 const rec = data.latest_recommendation;
 const appt = data.upcoming_appointment;
 const outcome = data.last_service_outcome;
 const c = data.counts || {};

 return (
 <div className="vhp-summary">
 <div className="vhp-summary__cards">
 <Card>
 <div className="vhp-card">
 <h3 className="vhp-card__title">Vehicle Details</h3>
 <p className="vhp-card__row">{v.make} {v.model}</p>
 <p className="vhp-card__row">Reg: {v.registration_number}</p>
 <p className="vhp-card__row">Mileage: {v.current_mileage}</p>
 <p className="vhp-card__row">Owner: {v.owner}</p>
 </div>
 </Card>
 <Card>
 <div className="vhp-card">
 <h3 className="vhp-card__title">Latest Recommendation</h3>
 <p className="vhp-card__row">{rec?.recommendation_issue || 'None'}</p>
 <p className="vhp-card__row">Priority: {rec?.priority || 'N/A'}</p>
 <p className="vhp-card__row">Confidence: {rec?.ai_confidence || 'N/A'}</p>
 </div>
 </Card>
 <Card>
 <div className="vhp-card">
 <h3 className="vhp-card__title">Upcoming Appointment</h3>
 <p className="vhp-card__row">{appt?.service_type || 'None scheduled'}</p>
 <p className="vhp-card__row">Date: {appt?.preferred_date || 'N/A'}</p>
 <p className="vhp-card__row">#{appt?.appointment_number || 'N/A'}</p>
 </div>
 </Card>
 <Card>
 <div className="vhp-card">
 <h3 className="vhp-card__title">Last Service Outcome</h3>
 <p className="vhp-card__row">{outcome?.outcome_type || 'None'}</p>
 <p className="vhp-card__row">Status: {outcome?.final_status || 'N/A'}</p>
 <p className="vhp-card__row">Date: {outcome?.outcome_date || 'N/A'}</p>
 </div>
 </Card>
 </div>
 <div className="vhp-summary__counts">
 <span>Services: {c.service_history ?? 0}</span>
 <span>Invoices: {c.invoices ?? 0}</span>
 <span>Recommendations: {c.recommendations ?? 0}</span>
 <span>Appointments: {c.appointments ?? 0}</span>
 <span>Inspections: {c.inspections ?? 0}</span>
 <span>Repair Plans: {c.repair_plans ?? 0}</span>
 <span>Outcomes: {c.service_outcomes ?? 0}</span>
 </div>
 </div>
 );
}
","import React from 'react';
import { NowRecordListConnected } from '@servicenow/react-components/NowRecordListConnected';
import { Button } from '@servicenow/react-components/Button';
import PassportSummary from './PassportSummary';

const SECTIONS = [
 { title: 'Service History', table: 'x_1947064_autoca_0_service_history',
 cols: 'service_date,service_details,service_center,mileage_at_service,service_cost' },
 { title: 'Invoices', table: 'x_1947064_autoca_0_invoice',
 cols: 'invoice_number,invoice_date,amount,payment_status,service_center' },
 { title: 'Recommendations', table: 'x_1947064_autoca_0_reccommendation',
 cols: 'recommendation_issue,priority,classification,due_date,ai_confidence' },
 { title: 'Appointments', table: 'x_1947064_autoca_0_appointment',
 cols: 'appointment_number,preferred_date,service_type,assigned_technician' },
 { title: 'Inspections', table: 'x_1947064_autoca_0_inspection',
 cols: 'inspection_number,inspection_date,finding,severity,status' },
 { title: 'Repair Plans', table: 'x_1947064_autoca_0_repair_plan',
 cols: 'repair_plan_number,repair_description,classification,estimated_cost,status' },
 { title: 'Service Outcomes', table: 'x_1947064_autoca_0_service_outcome',
 cols: 'outcome_number,outcome_date,outcome_type,final_status,quality_rating' },
];

interface Props {
 vehicleId: string;
 onBack: () => void;
}

export default function VehiclePassport({ vehicleId, onBack }: Props) {
 return (
 <div className="vhp-passport">
 <div className="vhp-passport__back">
 <Button label="← Back to Fleet" variant="secondary" onClick={onBack} />
 </div>
 <h2 className="vhp-passport__heading">Vehicle Health Passport</h2>
 <PassportSummary vehicleId={vehicleId} />
 {SECTIONS.map((s) => (
 <div key={s.table} className="vhp-passport__section">
 <h3 className="vhp-passport__section-title">{s.title}</h3>
 <NowRecordListConnected
 key={`vehicle=${vehicleId}`}
 table={s.table}
 columns={s.cols}
 hideHeader={true}
 />
 </div>
 ))}
 </div>
 );
}
","import React, { useState, useEffect, useCallback } from 'react';
import './app.css';
import VehicleList from './components/VehicleList';
import VehiclePassport from './components/VehiclePassport';

interface ViewState {
 view: string;
 id: string | null;
}

function getViewFromUrl(): ViewState {
 const params = new URLSearchParams(window.location.search);
 return {
 view: params.get('view') || 'list',
 id: params.get('id') || null,
 };
}

export default function App() {
 const [currentView, setCurrentView] = useState<ViewState>(getViewFromUrl);

 useEffect(() => {
 const onPopState = () => setCurrentView(getViewFromUrl());
 window.addEventListener('popstate', onPopState);
 return () => window.removeEventListener('popstate', onPopState);
 }, []);

 const navigate = useCallback(
 (view: string, id?: string | null) => {
 const params = new URLSearchParams({ view });
 if (id) params.set('id', id);
 const path = `${window.location.pathname}?${params}`;
 const title =
 view === 'passport' ? 'Vehicle Health Passport' : 'Vehicle Fleet';

 if (window.self !== window.top) {
 (window as any).CustomEvent.fireTop(
 'magellanNavigator.permalink.set',
 { relativePath: path, title }
 );
 }

 window.history.pushState({ view, id }, '', path);
 document.title = title;
 setCurrentView({ view, id: id || null });
 },
 []
 );

 const { view, id } = currentView;

 if (view === 'passport' && id) {
 return (
 <div className="vhp-app">
 <VehiclePassport
 vehicleId={id}
 onBack={() => navigate('list')}
 />
 </div>
 );
 }

 return (
 <div className="vhp-app">
 <VehicleList onSelect={(sysId) => navigate('passport', sysId)} />
 </div>
 );
}
